function _canPause(address _account) private view returns (bool) {
        return _account == owner() || pauseGuardians[_account];
    }

function _canUnpause(address _account) private view returns (bool) {
        return _account == owner() || unpauseAdmins[_account];
    }

function _isSignerLifecycleSelector(bytes4 _selector) private pure returns (bool) {
        return _selector == DROP_SIGNER_UPDATE_SELECTOR || _selector == DROP_SIGNER_EPOCH_SELECTOR
            || _selector == DROP_CANCEL_SELECTOR;
    }

function _setFunctionAdmin(address _address, address _target, bytes4 _selector, bool _status)
        private
    {
        require(_address != address(0), "Zero admin");
        require(_target != address(0), "Zero target");
        require(_selector != bytes4(0), "Zero selector");
        functionAdmin[_address][_target][_selector] = _status;
        emit FunctionAdminUpdated(_address, _target, _selector, _status, msg.sender);
    }

function _setSignerFunctionAdmin(
        address _address,
        address _target,
        bytes4 _selector,
        bool _status
    ) private {
        require(_isSignerLifecycleSelector(_selector), "Not signer selector");
        if (msg.sender != owner()) {
            require(signerLifecycleTargets[_target], "Not signer target");
        }
        _setFunctionAdmin(_address, _target, _selector, _status);
    }

function registerBatchFunctionAdmin(
        address _address,
        address _target,
        bytes4[] memory _selector,
        bool _status
    ) public onlyOwner {
        for (uint256 i = 0; i < _selector.length; i++) {
            _setFunctionAdmin(_address, _target, _selector[i], _status);
        }
    }

function isPaused(bytes32 _domain) public view returns (bool) {
        return pausedDomains[_domain];
    }

function registerBatchSignerFunctionAdmin(
        address _address,
        address _target,
        bytes4[] memory _selector,
        bool _status
    ) public signerManagerOrOwner {
        for (uint256 i = 0; i < _selector.length; i++) {
            _setSignerFunctionAdmin(_address, _target, _selector[i], _status);
        }
    }

function registerUnpauseAdmin(address _account, bool _status) public onlyOwner {
        require(_account != address(0), "Zero admin");
        unpauseAdmins[_account] = _status;
        emit UnpauseAdminUpdated(_account, _status, msg.sender);
    }

function retrieveFunctionAdmin(address _address, address _target, bytes4 _selector)
        public
        view
        returns (bool)
    {
        return functionAdmin[_address][_target][_selector];
    }

function retrieveCollectionAdmin(address, uint256) public pure returns (bool) {
        return false;
    }

function registerSignerFunctionAdmin(
        address _address,
        address _target,
        bytes4 _selector,
        bool _status
    ) public signerManagerOrOwner {
        _setSignerFunctionAdmin(_address, _target, _selector, _status);
    }

function isAdminContract() external pure returns (bool) {
        return true;
    }

function registerSignerManager(address _account, bool _status) public onlyOwner {
        require(_account != address(0), "Zero admin");
        signerManagers[_account] = _status;
        emit SignerManagerUpdated(_account, _status, msg.sender);
    }

function setPaused(bytes32 _domain, bool _paused, bytes32 _reason) public {
        require(_domain != bytes32(0), "Zero domain");
        if (_paused) {
            require(_canPause(msg.sender), "Not allowed");
        } else {
            require(_canUnpause(msg.sender), "Not allowed");
        }
        pausedDomains[_domain] = _paused;
        emit PauseUpdated(_domain, _paused, msg.sender, _reason);
    }

function registerSignerLifecycleTarget(address _target, bool _status) public onlyOwner {
        require(_target != address(0), "Zero target");
        signerLifecycleTargets[_target] = _status;
        emit SignerLifecycleTargetUpdated(_target, _status, msg.sender);
    }

function retrieveGlobalAdmin(address _address) public view returns (bool) {
        return adminPermissions[_address];
    }

function registerPauseGuardian(address _account, bool _status) public onlyOwner {
        require(_account != address(0), "Zero admin");
        pauseGuardians[_account] = _status;
        emit PauseGuardianUpdated(_account, _status, msg.sender);
    }

function registerFunctionAdmin(
        address _address,
        address _target,
        bytes4 _selector,
        bool _status
    ) public onlyOwner {
        _setFunctionAdmin(_address, _target, _selector, _status);
    }

function updateEmergencyRecipient(address _recipient) public onlyOwner {
        require(_recipient != address(0), "Zero recipient");
        address oldRecipient = emergencyRecipient;
        emergencyRecipient = _recipient;
        emit EmergencyRecipientUpdated(oldRecipient, _recipient, msg.sender);
    }

function registerAdmin(address _admin, bool _status) public onlyOwner {
        require(_admin != address(0), "Zero admin");
        adminPermissions[_admin] = _status;
        emit GlobalAdminUpdated(_admin, _status, msg.sender);
    }

constructor(address _tdhSigner) {
        require(_tdhSigner != address(0), "Zero tdh signer");
        tdhSigner = _tdhSigner;
        emergencyRecipient = owner();
    }

modifier signerManagerOrOwner() {
        require(msg.sender == owner() || signerManagers[msg.sender], "Not Allowed");
        _;
    }

function _requireValidKey(bytes32 evidenceId, uint64 evidenceVersion) private pure {
        if (evidenceId == bytes32(0) || evidenceVersion == 0) {
            revert ArtistArchiveInvalidEvidenceKey(evidenceId, evidenceVersion);
        }
    }

function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == type(IStreamArtistArchiveV2).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

function artistArchiveMarkerV2() external pure returns (bytes32) {
        return _MARKER;
    }

function artistArchiveSchemaV2() external pure returns (uint16) {
        return _SCHEMA_VERSION;
    }

function artistArchiveMaxEvidenceBytesV2() external pure returns (uint256) {
        return SSTORE2.MAX_DATA_LENGTH;
    }

function artistEvidenceBytesV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes memory evidence)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        evidence = SSTORE2.read(record.pointer);
        bytes32 observedHash = keccak256(evidence);
        if (evidence.length != record.payloadSize || observedHash != record.contentHash) {
            revert ArtistArchiveEvidenceCorrupted(
                evidenceId, evidenceVersion, record.contentHash, observedHash
            );
        }
    }

function artistEvidenceMetadataV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes32 contentHash, address pointer, uint32 payloadSize, uint64 appendedAtBlock)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        return (record.contentHash, record.pointer, record.payloadSize, record.appendedAtBlock);
    }

function appendArtistEvidenceV2(
        bytes32 evidenceId,
        uint64 evidenceVersion,
        bytes calldata evidence
    ) external returns (bytes32 contentHash, address pointer, bool appended) {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        _requireValidKey(evidenceId, evidenceVersion);
        uint256 payloadSize = evidence.length;
        if (payloadSize == 0) {
            revert ArtistArchiveEmptyEvidence(evidenceId, evidenceVersion);
        }
        if (payloadSize > SSTORE2.MAX_DATA_LENGTH) {
            revert ArtistArchiveEvidenceTooLarge(payloadSize, SSTORE2.MAX_DATA_LENGTH);
        }
        if (block.number > type(uint64).max) {
            revert ArtistArchiveBlockNumberOverflow(block.number);
        }

…
        record.appendedAtBlock = uint64(block.number);
        record.contentHash = contentHash;
        emit ArtistArchiveEvidenceAppendedV2(
            evidenceId, evidenceVersion, contentHash, pointer, payloadSize
        );
        return (contentHash, pointer, true);
    }

constructor(address artistRegistry_, address operationCoordinator_) {
        if (artistRegistry_ == address(0) || operationCoordinator_ == address(0)) {
            revert ArtistArchiveInvalidBinding(artistRegistry_, operationCoordinator_);
        }
        artistRegistry = artistRegistry_;
        operationCoordinator = operationCoordinator_;
        artistArchiveBindingHashV2 = keccak256(
            abi.encode(
                _BINDING_DOMAIN,
                block.chainid,
                artistRegistry_,
                operationCoordinator_,
                type(IStreamArtistArchiveV2).interfaceId,
                _MARKER,
                _SCHEMA_VERSION,
                SSTORE2.MAX_DATA_LENGTH
            )
        );
    }

function _externalProviderBindingHash(
        ArtistExternalProviderV2 provider,
        ArtistDirectoryPinV2 memory pin
    ) private view returns (bytes32) {
        return keccak256(
            abi.encode(
                _EXTERNAL_PROVIDER_BINDING_DOMAIN,
                block.chainid,
                _providerId(provider),
                pin.expectedAddress,
                pin.expectedRuntimeCodeHash,
                pin.expectedInterfaceId,
                pin.expectedMarkerHash,
                pin.expectedSchemaHash
            )
        );
    }

function _pinHash(ArtistDirectoryPinV2 memory pin) private pure returns (bytes32) {
        return keccak256(
            abi.encode(
                pin.expectedAddress,
                pin.expectedRuntimeCodeHash,
                pin.expectedInterfaceId,
                pin.expectedMarkerHash,
                pin.expectedSchemaHash,
                pin.expectedBindingHash
            )
        );
    }

function _providerId(ArtistExternalProviderV2 provider) private pure returns (bytes32) {
        if (provider == ArtistExternalProviderV2.RoleRegistry) {
            return keccak256("provider:role_registry");
        }
        if (provider == ArtistExternalProviderV2.Core) {
            return keccak256("provider:core");
        }
        if (provider == ArtistExternalProviderV2.GovernanceV2) {
            return keccak256("provider:governance_v2");
        }
        if (provider == ArtistExternalProviderV2.FinalityRegistry) {
            return keccak256("provider:finality_registry");
        }
        return keccak256("provider:import_continuity");
    }

function _requireUniqueAddress(
        address[] memory seenAddresses,
        uint256 seenCount,
        address expectedAddress
    ) private view returns (uint256) {
        if (expectedAddress == address(this)) {
            revert ArtistRegistryPinAddressAlias(expectedAddress);
        }
        for (uint256 i = 0; i < seenCount; i++) {
            if (seenAddresses[i] == expectedAddress) {
                revert ArtistRegistryPinAddressAlias(expectedAddress);
            }
        }
        seenAddresses[seenCount] = expectedAddress;
        return seenCount + 1;
    }

function _storePin(ArtistDirectoryPinV2 storage target, ArtistDirectoryPinV2 memory source)
        private
    {
        target.expectedAddress = source.expectedAddress;
        target.expectedRuntimeCodeHash = source.expectedRuntimeCodeHash;
        target.expectedInterfaceId = source.expectedInterfaceId;
        target.expectedMarkerHash = source.expectedMarkerHash;
        target.expectedSchemaHash = source.expectedSchemaHash;
        target.expectedBindingHash = source.expectedBindingHash;
    }

function _validatePin(ArtistDirectoryPinV2 memory pin, uint8 pinClass, uint8 pinIndex)
        private
        pure
    {
        if (
            pin.expectedAddress == address(0) || pin.expectedRuntimeCodeHash == bytes32(0)
                || pin.expectedRuntimeCodeHash == _EMPTY_CODE_HASH
                || pin.expectedInterfaceId == bytes4(0)
                || pin.expectedInterfaceId == bytes4(0xffffffff)
                || pin.expectedMarkerHash == bytes32(0) || pin.expectedSchemaHash == bytes32(0)
                || pin.expectedBindingHash == bytes32(0)
        ) {
            revert ArtistRegistryInvalidPin(pinClass, pinIndex);
        }
    }

function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == type(IStreamArtistRegistryV2).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

function artistRegistryBindingHashV2() external view returns (bytes32) {
        return _registryBindingHash;
    }

function artistRecipeSetHashV2() external view returns (bytes32) {
        return _recipeSetHash;
    }

function artistArchivePinV2() external view returns (ArtistDirectoryPinV2 memory) {
        return _archive;
    }

function artistSemanticOwnerPinV2(ArtistSemanticDomainV2 domain)
        external
        view
        returns (ArtistDirectoryPinV2 memory)
    {
        return _semanticOwners[uint8(domain)];
    }

function artistRegistrySchemaHashV2() external pure returns (bytes32) {
        return _SCHEMA_HASH;
    }

function artistCoordinatorPinV2() external view returns (ArtistDirectoryPinV2 memory) {
        return _operationCoordinator;
    }
